#!/bin/bash
# MEATCORES - standalone MiSTer downloader and 320x240 DOS-style frontend.
# Includes a dedicated Boomer-derived FPGA display. Python 3, no pip packages.
# Install this file in /media/fat/Scripts. Assets follow the database paths.
# Native 320x240 / 15.7 kHz video; HDMI/DV/scaler routing follows MiSTer settings.
# Controls: arrows / D-pad move; A / Enter select; B / Escape exit; X / Shift download.
# Update Only selects installed games with changed/missing DB files. Exact matches
# are disabled. Newer local RBFs are protected. Alternatives accompany each game.
# Systems and standalone games are ordered by newest RBF release date first.
# Downloads are size/MD5 verified, staged, then placed at the exact DB paths.
# The current DB contains MRAs and RBFs, not MAME ROM archives.
# Menu music: “Blue Space” by FoxSynergy (CC-BY 3.0), OpenGameArt.org.
# Source page: https://opengameart.org/content/blue-space
# Exit restores menu.rbf. No MiSTer.ini changes or background service are installed.
# Display hardware source and its license notices are embedded in this same file:
#     bash MEATCORES.sh --extract-display-source ./meatcores-display-source
# Build that source using Quartus 17.0.2: quartus_sh --flow compile VoidSW
set -eu
if ! command -v python3 >/dev/null 2>&1; then
    printf 'MEATCORES requires Python 3 (included with current MiSTer Linux).\n'
    exit 1
fi
export MEATCORES_SELF="$(readlink -f "$0")"
exec python3 - "$@" <<'MEATCORES_PY'
import argparse, base64, collections, concurrent.futures, ctypes, fcntl
import hashlib, io, json, mmap, os, pathlib, re, shutil, signal
import struct, sys, tarfile, tempfile, threading, time, urllib.parse, urllib.request
import zipfile, zlib, subprocess, select, queue
import xml.etree.ElementTree as ET

# Increment for each published script release. Development modes never self-update.
SCRIPT_VERSION = 2026091301
SELF_TREE_URL = 'https://api.github.com/repos/meathax/meatscript/git/trees/main'
SELF_RAW_URL = 'https://raw.githubusercontent.com/meathax/meatscript/main/MEATCORES.sh'

def self_update():
    target = pathlib.Path(os.environ.get('MEATCORES_SELF', '')).resolve()
    if os.environ.pop('MEATCORES_UPDATED', '') == str(target): return
    temporary = None
    try:
        current = target.read_bytes()
        def blob_hash(data):
            return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
        def get(url):
            return urllib.request.urlopen(urllib.request.Request(url, headers={
                'User-Agent': 'MEATCORES', 'Accept': 'application/vnd.github+json'}), timeout=2)
        with get(SELF_TREE_URL) as response:
            raw = response.read(65537)
        if len(raw) > 65536: return
        entry = next((e for e in json.loads(raw).get('tree', [])
                      if e.get('path') == 'MEATCORES.sh' and e.get('type') == 'blob'), None)
        if not entry or entry['sha'] == blob_hash(current): return
        size = entry.get('size', 0)
        if not 0 < size <= 8*1024*1024: return
        data, deadline = bytearray(), time.monotonic()+6
        with get(SELF_RAW_URL) as response:
            while len(data) <= size:
                if time.monotonic() > deadline: return
                block = response.read(min(65536, size+1-len(data)))
                if not block: break
                data.extend(block)
        data = bytes(data)
        if len(data) != size or blob_hash(data) != entry['sha']: return
        match = re.search(rb'^SCRIPT_VERSION = ([0-9]+)$', data, re.M)
        if not match or int(match[1]) <= SCRIPT_VERSION: return
        if not data.startswith(b'#!/bin/bash\n'): return
        payload = data.split(b"<<'MEATCORES_PY'\n", 1)[1].rsplit(b'\nMEATCORES_PY', 1)[0]
        compile(payload, str(target), 'exec')
        fd, name = tempfile.mkstemp(prefix='.MEATCORES-update-', dir=target.parent)
        temporary = pathlib.Path(name)
        with os.fdopen(fd, 'wb') as out:
            out.write(data); out.flush(); os.fsync(out.fileno())
        temporary.chmod(target.stat().st_mode & 0o777 | 0o100)
        check = subprocess.run(['/bin/bash','-n',str(temporary)], stdout=subprocess.DEVNULL,
                               stderr=subprocess.DEVNULL, timeout=2)
        if check.returncode: return
        os.replace(temporary, target)
        temporary = None
        env = dict(os.environ, MEATCORES_UPDATED=str(target))
        os.execve('/bin/bash', ['/bin/bash',str(target)]+sys.argv[1:], env)
    except Exception:
        # Network, validation or read-only media failures must never block launch.
        pass
    finally:
        if temporary is not None:
            try: temporary.unlink()
            except OSError: pass


DB_URL = 'https://raw.githubusercontent.com/meathax/meatcores/db/db.json.zip'
ROOT = pathlib.Path('/media/fat')
SYSTEMS = {'Bucky': "Bucky O'Hare", 'DoCastle': 'Universal Do! Series',
           'DrMicro': 'Dr. Micro', 'EscapeKids': 'Escape Kids', 'I-Robot': 'I, Robot',
           'Ikki': 'Ikki', 'MCR68': 'Midway MCR 68K', 'NARC': 'NARC',
           'SSV': 'Sammy SSV', 'SegaSystem32Multi': 'Sega System 32 Multi',
           'SegaSystem32': 'Sega System 32', 'Segas24': 'Sega System 24',
           'Suna8bit': 'SunA 8-bit', 'YellowCab': 'Yellow Cab'}
LIMIT_DB = 8 * 1024 * 1024

def digest(path, cancel=None):
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for block in iter(lambda: f.read(262144), b''):
            if cancel is not None and cancel.is_set(): raise Cancelled()
            h.update(block)
    return h.hexdigest()

def safe_path(root, relative):
    if not isinstance(relative, str) or '\\' in relative or ':' in relative:
        raise ValueError('Invalid database path')
    parts = pathlib.PurePosixPath(relative)
    if parts.is_absolute() or any(p in ('', '.', '..') for p in relative.split('/')):
        raise ValueError('Unsafe database path: ' + relative)
    if any(ord(c) < 32 for c in relative):
        raise ValueError('Control character in database path')
    target = root.joinpath(*parts.parts)
    if root.resolve() not in target.resolve().parents:
        raise ValueError('Path escapes installation root: ' + relative)
    return target

def verified(path, meta, cancel=None):
    try:
        return path.is_file() and path.stat().st_size == meta['size'] and digest(path,cancel) == meta['hash']
    except OSError:
        return False

def url_for(db, path):
    url = db['files'][path].get('url') or db.get('base_files_url', '') + urllib.parse.quote(path, safe='/')
    if urllib.parse.urlsplit(url).scheme != 'https':
        raise ValueError('Database download URL must use HTTPS')
    return url

def request(url, method=None):
    return urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'MEATCORES/1.0'}, method=method), timeout=20)

def parse_db(data):
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        members = archive.infolist()
        if len(members) != 1 or members[0].file_size > LIMIT_DB:
            raise ValueError('Invalid database archive')
        db = json.loads(archive.read(members[0]))
    if db.get('v') != 1 or db.get('db_id') != 'meathax/meatcores':
        raise ValueError('Unsupported database version or identity')
    if not isinstance(db.get('files'), dict) or not db['files']:
        raise ValueError('Empty database')
    for path, meta in db['files'].items():
        safe_path(ROOT, path)
        h = str(meta.get('hash', ''))
        if not re.fullmatch('[0-9a-fA-F]{1,32}', h):
            raise ValueError('Invalid MD5: ' + path)
        meta['hash'] = h.lower().zfill(32)  # Downloader permits omitted leading zeroes.
        if type(meta.get('size')) is not int or not 0 <= meta['size'] <= 2**31:
            raise ValueError('Invalid size: ' + path)
        if 'zip_id' in meta:
            raise ValueError('Archive-backed entries need a newer MEATCORES version')
        url_for(db, path)
    return db

def load_db(cache):
    # Always request the DB on launch. Cached catalogues are view-only when offline.
    try:
        with request(DB_URL) as response:
            raw = response.read(LIMIT_DB + 1)
        if len(raw) > LIMIT_DB:
            raise ValueError('Database exceeds size limit')
        db = parse_db(raw)
        cache.mkdir(parents=True, exist_ok=True)
        tmp = cache / 'db.tmp'
        tmp.write_bytes(raw)
        os.replace(tmp, cache / 'db.zip')
        return db, True, ''
    except Exception as error:
        if (cache / 'db.zip').exists():
            return parse_db((cache / 'db.zip').read_bytes()), False, 'OFFLINE: cached list; downloads disabled'
        raise RuntimeError('Cannot fetch database: ' + str(error)) from error

def slug(value):
    return re.sub('[^a-z0-9]', '', value.lower())

def core_id(path):
    return re.sub(r'_\d{8}$', '', pathlib.PurePosixPath(path).stem).removeprefix('Arcade-')

def core_date(path):
    match = re.search(r'_(\d{8})\.rbf$', path, re.I)
    return match.group(1) if match else ''

# Explicit per-set disk requirements. Do not infer disk format from a game name.
# Example when adding a disk-backed core (use its documented output filename):
# 'setname': [{'chd': 'setname/disk.chd', 'output': 'disk.vhd', 'format': 'vhd'}]
# format='vhd' means the raw hard-disk image used by MiSTer, not a Microsoft
# dynamic VHD container. format='chd' installs the compressed image unchanged.
# The Downloader DB may also provide this mapping under 'meatcores_disks'.
DISK_REQUIREMENTS = {}
CHD_ITEMS = ('mame-chd-collection_01', 'mame-chd-collection_02')
CHDMAN_URL = ('https://raw.githubusercontent.com/emmercm/chdman-js/'
              'b0b3337cfd8a784f7e72a2a38a70b07cabeb2425/'
              'packages/chdman-linux-arm/chdman-armv7')
CHDMAN_SHA256 = 'da0ce2f11199823b090f81e52513cf78be22158d4210fa79bc34e8ec4a9386e5'
CHDMAN_SIZE = 1239452

def disk_specs(data, mapping=None):
    setname = (ET.fromstring(data).findtext('setname') or '').strip()
    specs = (DISK_REQUIREMENTS if mapping is None else mapping).get(setname, [])
    for spec in specs:
        if not re.fullmatch(r'[A-Za-z0-9_-]+', setname):
            raise ValueError('Unsafe disk set name')
        name = spec['output']
        if not re.fullmatch(r'[A-Za-z0-9_. -]+', name) or '..' in name:
            raise ValueError('Unsafe disk output filename')
        if spec['format'] not in ('chd', 'vhd'):
            raise ValueError('Unsupported disk output format')
        source = pathlib.PurePosixPath(spec['chd'])
        if source.is_absolute() or '..' in source.parts or len(source.parts) != 2 or source.suffix != '.chd':
            raise ValueError('Unsafe CHD source path')
    return [(setname, dict(spec)) for spec in specs]

def prepare_disks(library, declarations, folder, progress, cancel):
    needed = []
    for g in library.games:
        for p in list(g['files']):
            for setname, spec in declarations.get(p, []):
                target = folder+'/chd/'+setname+'/'+spec['output']
                if not safe_path(library.root, target).is_file():
                    needed.append((g, target, spec))
    if not needed: return
    progress('READING CHD ARCHIVE INDEXES')
    def index(item):
        if cancel is not None and cancel.is_set(): raise Cancelled()
        with request('https://archive.org/metadata/'+item) as response:
            raw = response.read(16*1024*1024+1)
        if len(raw) > 16*1024*1024: raise RuntimeError('CHD index too large')
        return {f['name'][len('MAME CHDs (merged)/'):]: dict(f, item=item)
                for f in json.loads(raw)['files'] if f.get('name', '').startswith('MAME CHDs (merged)/')
                and f['name'].endswith('.chd') and not f.get('private')}
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        indexes = list(pool.map(index, CHD_ITEMS))
    for g, target, spec in needed:
        entry = next((idx[spec['chd']] for idx in indexes if spec['chd'] in idx), None)
        if entry is None:
            g['rom_error'] = 'CHD unavailable: '+spec['chd']
            continue
        meta = {'disk': spec, 'size': int(entry['size']), 'hash': entry['md5'].zfill(32),
                'overwrite': False, 'url': 'https://archive.org/download/'+entry['item']+'/'+
                urllib.parse.quote(entry['name'], safe='/')}
        if target in library.db['files'] and library.db['files'][target] != meta:
            raise ValueError('Conflicting disk requirements: '+target)
        library.db['files'][target] = meta
        if target not in g['files']: g['files'].append(target)

def chdman(stage, cancel):
    tool = stage/'chdman'
    if tool.is_file():
        if tool.stat().st_size == CHDMAN_SIZE and hashlib.sha256(tool.read_bytes()).hexdigest() == CHDMAN_SHA256:
            return tool
        tool.unlink()
    with request(CHDMAN_URL) as response, open(tool, 'wb') as out:
        h, size = hashlib.sha256(), 0
        while True:
            if cancel.is_set(): raise Cancelled()
            block = response.read(65536)
            if not block: break
            size += len(block)
            if size > CHDMAN_SIZE: raise RuntimeError('Invalid chdman size')
            h.update(block); out.write(block)
    if size != CHDMAN_SIZE or h.hexdigest() != CHDMAN_SHA256:
        raise RuntimeError('chdman checksum failed')
    tool.chmod(0o755)
    return tool

def run_chdman(tool, args, cancel, progress, label):
    proc = subprocess.Popen([str(tool)]+args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                            env=dict(os.environ, LC_ALL='C'))
    output, fraction = '', 0.0
    try:
        progress(label, 0)
        while True:
            if cancel.is_set(): raise Cancelled()
            ready, _, _ = select.select([proc.stdout], [], [], 0.1)
            if ready:
                data = os.read(proc.stdout.fileno(), 4096)
                if data:
                    output = (output + data.decode('utf-8', 'replace'))[-8192:]
                    matches = re.findall(r'([0-9]+(?:[.][0-9]+)?)%', output)
                    if matches: fraction = min(1.0, float(matches[-1])/100)
                    progress(label, fraction)
                elif proc.poll() is not None: break
            elif proc.poll() is not None: break
        if proc.wait() != 0: raise RuntimeError(label+' failed: '+output[-400:])
        progress(label, 1)
        return output
    finally:
        if proc.poll() is None:
            proc.terminate()
            try: proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill(); proc.wait()
        proc.stdout.close()

def extract_disk(dest, meta, stage, cancel, progress):
    if meta['disk']['format'] == 'chd': return
    # Downloaded CHDs and chdman share the same private transaction directory.
    source = stage/('disk-'+hashlib.sha256(str(dest).encode()).hexdigest()[:16]+'.chd')
    os.replace(dest, source)
    with source.open('rb') as f: header = f.read(124)
    if len(header) != 124 or header[:8] != b'MComprHD' or struct.unpack('>II', header[8:16]) != (124,5):
        raise RuntimeError('VHD extraction requires a version 5 CHD')
    if any(header[104:124]): raise RuntimeError('Parent-dependent CHD needs an explicit parent mapping')
    logical = struct.unpack('>Q', header[32:40])[0]
    expected = header[64:84].hex()
    if not logical or not any(header[64:84]): raise RuntimeError('CHD lacks a verified raw disk checksum')
    if shutil.disk_usage(stage).free < logical + 4*1024*1024:
        raise RuntimeError('Not enough space for extracted VHD (%d bytes)' % logical)
    tool = chdman(stage, cancel)
    info = run_chdman(tool, ['info','-i',str(source)], cancel, progress, 'CHECKING DISK TYPE')
    if 'GDDD' not in info: raise RuntimeError('CHD is not a hard disk; VHD extraction refused')
    run_chdman(tool, ['extracthd','-i',str(source),'-o',str(dest)], cancel, progress,
               'EXTRACTING VHD '+dest.name)
    if not dest.is_file() or dest.stat().st_size != logical:
        raise RuntimeError('Extracted VHD size mismatch')
    h, count = hashlib.sha1(), 0
    with dest.open('rb') as f:
        while True:
            if cancel.is_set(): raise Cancelled()
            block = f.read(262144)
            if not block: break
            h.update(block); count += len(block)
            progress('VERIFYING VHD '+dest.name, count/logical)
    if h.hexdigest() != expected: raise RuntimeError('Extracted VHD SHA1 mismatch')
    with dest.open('rb') as f: os.fsync(f.fileno())
    # Keep source until the whole installation commits. The transaction's finally
    # removes the downloaded CHD, helper and partial outputs on all exit paths.

ROM_ITEM = 'https://archive.org/download/mame-roms-merged_/'

# A compact 32 kbps Amiga-like loop (about 3 minutes). Keeping the
# source URL and digest here lets the launcher ship as one script while still
# refusing altered or incomplete audio. The file is cached beside the launcher.
MUSIC_URL = ('https://opengameart.org/sites/default/files/'
             'Blue%20Space%20v0_8%20%2832%20kbps%29.mp3')
MUSIC_SHA256 = 'edebe445c12a1f8f8f447ad9cf08c9ffb2587d0b453771b0701d0cb9856d1b4a'
MUSIC_SIZE = 773773
MUSIC_FILE = 'MEATCORES_MENU.mp3'

class MenuMusic:
    """Download and loop the tiny menu track without touching the UI thread."""
    def __init__(self, cache):
        self.cache = cache
        self.path = cache/MUSIC_FILE
        self.cancel = threading.Event()
        self.ready = threading.Event()
        self.lock = threading.Lock()
        self.player = None
        self.thread = None
        # Development previews and catalogue tools must stay completely silent;
        # MiSTer is the only target with the ALSA player used below.
        if os.uname().machine != 'armv7l' or shutil.which('mpg123') is None:
            return
        self.thread = threading.Thread(target=self._run, name='meatcores-music', daemon=True)
        self.thread.start()

    def _valid(self):
        try:
            return (self.path.is_file() and self.path.stat().st_size == MUSIC_SIZE and
                    hashlib.sha256(self.path.read_bytes()).hexdigest() == MUSIC_SHA256)
        except OSError:
            return False

    def _download(self):
        data = bytearray()
        try:
            with request(MUSIC_URL) as response:
                while True:
                    if self.cancel.is_set(): return False
                    block = response.read(65536)
                    if not block: break
                    data.extend(block)
                    if len(data) > MUSIC_SIZE: return False
            if len(data) != MUSIC_SIZE or hashlib.sha256(data).hexdigest() != MUSIC_SHA256:
                return False
            if self.cancel.is_set(): return False
            fd, name = tempfile.mkstemp(prefix='.meatcores-music-', dir=self.cache)
            temporary = pathlib.Path(name)
            try:
                with os.fdopen(fd, 'wb') as output:
                    output.write(data); output.flush(); os.fsync(output.fileno())
                if self.cancel.is_set(): return False
                os.replace(temporary, self.path)
                temporary = None
                return True
            finally:
                if temporary is not None and temporary.exists(): temporary.unlink()
        except (OSError, IOError, ValueError):
            return False

    def _play_loop(self):
        with self.lock:
            if self.cancel.is_set(): return
            try:
                player = subprocess.Popen(
                    ['mpg123', '-q', '--loop', '-1', str(self.path)], stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    close_fds=True, start_new_session=True)
            except OSError:
                return
            self.player = player
        # mpg123 owns the loop; this watcher only waits cheaply for exit/cancel.
        while not self.cancel.wait(.20):
            if player.poll() is not None:
                with self.lock:
                    if self.player is player: self.player = None
                return
        self._stop_player()

    def _run(self):
        if not self._valid() and not self._download(): return
        if self._valid() and self.ready.wait(): self._play_loop()

    def begin(self):
        """Allow playback once the first menu frame is visible."""
        self.ready.set()

    def _stop_player(self):
        with self.lock:
            player, self.player = self.player, None
        if player is None: return
        try:
            if player.poll() is None: player.terminate()
            player.wait(timeout=.75)
        except (OSError, subprocess.TimeoutExpired):
            try: player.kill(); player.wait(timeout=.25)
            except (OSError, subprocess.TimeoutExpired): pass

    def close(self):
        self.cancel.set()
        self.ready.set()
        self._stop_player()
        if self.thread is not None:
            self.thread.join(timeout=1.0)
        self._stop_player()

class RomSearch(list):
    def __init__(self, names, crcs):
        super().__init__(names)
        self.crcs = crcs

def rom_names(data):
    tree = ET.fromstring(data)
    result = []
    for rom in tree.iter('rom'):
        names = []
        for name in rom.get('zip', '').split('|'):
            name = name.strip()
            if not name: continue
            if not re.fullmatch(r'[A-Za-z0-9_.-]+\.zip', name) or '..' in name:
                raise ValueError('Unsafe MRA ROM filename: ' + name)
            names.append(name)
        if names:
            crcs = {int(part.get('crc'),16) for part in rom.iter('part')
                    if re.fullmatch(r'[0-9a-fA-F]{8}',part.get('crc',''))}
            result.append(RomSearch(names,crcs))
    return result

def rom_present(root, folder, names):
    existing = []
    for name in names:
        path = safe_path(root,folder+'/'+name)
        if path.is_file(): existing.append(path)
    if not existing: return False
    if len(existing)==len(names) or not getattr(names,'crcs',None): return True
    # Check only ZIP directory CRCs (no decompression): a merged parent can
    # satisfy a missing clone ZIP, but a clone-only ZIP may still need its parent.
    available = set()
    for path in existing:
        try:
            with zipfile.ZipFile(path) as archive: available.update(info.CRC for info in archive.infolist())
        except (OSError,zipfile.BadZipFile): continue
    return names.crcs <= available

def resolve_roms(library, progress, cancel):
    checked = {}
    for i in library.selected:
        if not library.eligible(i): continue
        g = library.games[i]
        for names in g.get('rom_groups', []):
            if rom_present(library.root, library.rom_folder, names): continue
            available = False
            for name in names:
                if cancel.is_set(): raise Cancelled()
                target = library.rom_folder+'/'+name
                if safe_path(library.root, target).is_file():
                    available = True
                    continue
                if name not in checked:
                    progress('CHECKING ROM '+name, 0)
                    url = ROM_ITEM+urllib.parse.quote('MAME ROMs (merged)/'+name, safe='/')
                    try:
                        with request(url, method='HEAD') as response:
                            size = int(response.headers.get('Content-Length', '0'))
                        if size <= 0: raise RuntimeError('ROM size unavailable: '+name)
                        checked[name] = {'size':size, 'url':url, 'rom':True, 'overwrite':False}
                    except urllib.error.HTTPError as exc:
                        exc.close()
                        if exc.code != 404: raise
                        checked[name] = None
                meta = checked[name]
                if meta is None: continue
                available = True
                library.db['files'][target] = meta
                library.states[target] = 'NEW'
                if target not in g['files']: g['files'].append(target)
            if not available: raise RuntimeError('ROM unavailable in Archive: '+'|'.join(names))

def prepare_roms(library, cache, progress=lambda s: None, cancel=None):
    # Cache MRA descriptions by DB hash; never trust an obsolete local MRA.
    cache.mkdir(parents=True, exist_ok=True)
    mras = sorted({p for g in library.games for p in g['files'] if p.lower().endswith('.mra')})
    def read_mra(p):
        if cancel is not None and cancel.is_set(): raise Cancelled()
        meta = library.db['files'][p]
        local = safe_path(library.root, p)
        cached = cache / (meta['hash'] + '.mra')
        data = None
        for source in (local,cached):
            try: candidate = source.read_bytes()
            except OSError: continue
            if len(candidate)==meta['size'] and hashlib.md5(candidate).hexdigest()==meta['hash']:
                data = candidate; break
        if data is None:
            with request(url_for(library.db, p)) as response:
                data = response.read(meta['size']+1)
            if len(data)!=meta['size'] or hashlib.md5(data).hexdigest()!=meta['hash']:
                raise RuntimeError('MRA verification failed: '+p)
            cached.write_bytes(data)
        return p, (rom_names(data), disk_specs(data, library.db.get('meatcores_disks')))
    progress('CHECKING ROM REQUIREMENTS')
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        requirements = dict(pool.map(read_mra, mras))
    # FAT is case insensitive; preserve the existing spelling for other filesystems.
    folder = 'games/MAME' if (library.root/'games/MAME').is_dir() else 'games/mame'
    library.rom_folder = folder
    for g in library.games:
        g['rom_error'] = ''
        groups = {}
        for p in g['files']:
            for names in requirements.get(p, ([], []))[0]:
                group = groups.setdefault(tuple(names),RomSearch(names,set()))
                group.crcs.update(names.crcs)
        g['rom_groups'] = list(groups.values())

    prepare_disks(library, {p: pair[1] for p, pair in requirements.items()}, folder, progress, cancel)

class Library:
    def __init__(self, db, root):
        self.db, self.root = db, root
        self.games, self.groups, self.states = [], collections.OrderedDict(), {}
        self.selected = set()
        files = db['files']
        tag_ids = {v for k, v in db.get('tag_dictionary', {}).items() if k.startswith('arcadearcade')}
        rbfs = [p for p in files if p.lower().endswith('.rbf')]
        primaries = [p for p in files if p.lower().endswith('.mra') and '/_alternatives/' not in p]
        alts = [p for p in files if '/_alternatives/' in p and p.lower().endswith('.mra')]
        owned_alts = set()
        alternatives_by_game = collections.defaultdict(list)
        for alt in alts:
            alternatives_by_game[slug(pathlib.PurePosixPath(alt).parent.name)].append(alt)
        for p in primaries:
            tags = set(files[p].get('tags', [])) & tag_ids
            cores = [r for r in rbfs if tags & set(files[r].get('tags', []))]
            if len(cores) != 1:
                raise ValueError('Cannot unambiguously link MRA to RBF: ' + p)
            core = cores[0]
            name = pathlib.PurePosixPath(p).stem
            variants = alternatives_by_game.get(slug(name), [])
            owned_alts.update(variants)
            assets = [a for a in files if not a.lower().endswith(('.mra', '.rbf'))
                      and tags & set(files[a].get('tags', []))]
            self.games.append({'name': name, 'mra': p, 'core': core, 'files': sorted(set([p, core] + variants + assets)),
                               'system': SYSTEMS.get(core_id(core), core_id(core)), 'variants': len(variants),
                               'date': core_date(core)})
        # Do not silently omit new alternative directory naming conventions.
        if set(alts) - owned_alts:
            raise ValueError('Unmatched alternative MRA: ' + sorted(set(alts) - owned_alts)[0])
        unmapped = set(files) - {p for g in self.games for p in g['files']}
        if unmapped:
            raise ValueError('Unmapped database dependency: ' + sorted(unmapped)[0])
        self.games.sort(key=lambda g: (-int(g['date'] or '0'),g['system'].casefold(),g['name'].casefold()))
        for i, g in enumerate(self.games):
            self.groups.setdefault(g['system'], []).append(i)

    def scan(self, progress=lambda s: None, cancel=None):
        states, version_index, rom_checks = {}, {}, {}
        def missing_rom(names):
            key = (tuple(names),frozenset(names.crcs))
            if key not in rom_checks:
                rom_checks[key] = not rom_present(self.root,self.rom_folder,names)
            return rom_checks[key]
        paths = sorted({p for g in self.games for p in g['files']})
        for n, p in enumerate(paths):
            if cancel is not None and cancel.is_set(): raise Cancelled()
            progress('VERIFYING FILES %d/%d' % (n + 1, len(paths)))
            target = safe_path(self.root, p)
            meta = self.db['files'][p]
            state = 'CURRENT' if (target.is_file() if (meta.get('rom') or meta.get('disk')) else verified(target, meta, cancel)) else ('REPAIR' if target.exists() else 'NEW')
            if p.lower().endswith('.rbf'):
                date = core_date(p)
                if target.parent not in version_index:
                    families = collections.defaultdict(list)
                    for q in target.parent.glob('*.rbf'):
                        if cancel is not None and cancel.is_set(): raise Cancelled()
                        families[core_id(q.name)].append(q)
                    version_index[target.parent] = families
                versions = version_index[target.parent].get(core_id(p), [])
                if date and any(core_date(q.name) > date for q in versions):
                    state = 'LOCAL NEWER'
                elif state != 'CURRENT' and date and any(core_date(q.name) < date for q in versions):
                    state = 'UPDATE'
            states[p] = state
        for g in self.games:
            current = [states[p] for p in g['files']]
            if g.get('rom_groups'):
                g['rom_missing'] = any(missing_rom(names) for names in g['rom_groups'])
            g['installed'] = safe_path(self.root, g['mra']).is_file()
            if 'LOCAL NEWER' in current:
                g['state'] = 'LOCAL NEWER'
            elif all(s == 'CURRENT' for s in current) and not g.get('rom_error') and not g.get('rom_missing'):
                g['state'] = 'CURRENT'
            elif 'UPDATE' in current and g['installed']:
                g['state'] = 'UPDATE'
            elif g['installed']:
                # Changed MRAs have no release date; they are not proof of a newer core.
                g['state'] = 'REPAIR'
            else:
                g['state'] = 'NEW'
            g['blocked'] = any(self.db['files'][p].get('overwrite', True) is False
                               and safe_path(self.root, p).exists() and states[p] != 'CURRENT' for p in g['files'])
            if g['blocked']:
                g['state'] = 'PROTECTED'
        self.states = states
        self.selected.intersection_update(i for i in range(len(self.games)) if self.eligible(i))

    def eligible(self, i):
        return self.games[i].get('state') in ('NEW', 'UPDATE', 'REPAIR')

    def choose(self, ids):
        eligible = set(i for i in ids if self.eligible(i))
        if eligible and eligible <= self.selected:
            self.selected -= eligible
        else:
            self.selected |= eligible

    def updates(self):
        self.selected = {i for i, g in enumerate(self.games) if g.get('installed') and self.eligible(i)}

    def plan(self):
        return sorted({p for i in self.selected if self.eligible(i) for p in self.games[i]['files']
                       if self.states[p] != 'CURRENT'}, key=lambda p: (p.lower().endswith('.mra'), p))

class Cancelled(Exception):
    pass

def install(library, cancel, progress):
    resolve_roms(library, progress, cancel)
    for i in library.selected:
        if library.games[i].get('rom_error'):
            raise RuntimeError(library.games[i]['rom_error'])
    paths = [p for p in library.plan()
             if not ((library.db['files'][p].get('rom') or library.db['files'][p].get('disk')) and safe_path(library.root, p).is_file())]
    if not paths:
        return 0
    total = sum(library.db['files'][p]['size'] for p in paths)
    backups = sum(safe_path(library.root,p).stat().st_size for p in paths if safe_path(library.root,p).is_file())
    if shutil.disk_usage(library.root).free < total + backups + 4 * 1024 * 1024:
        raise RuntimeError('Not enough free space to stage selected files')
    # Stage everything before committing: failed/cancelled downloads leave installations intact.
    stage = pathlib.Path(tempfile.mkdtemp(prefix='.meatcores-', dir=library.root))
    completed, preserve_stage = 0, False
    try:
        for index, p in enumerate(paths):
            if cancel.is_set():
                raise Cancelled()
            meta = library.db['files'][p]
            dest = safe_path(stage, p)
            dest.parent.mkdir(parents=True, exist_ok=True)
            error = None
            for attempt in range(3):
                try:
                    got = 0
                    with request(url_for(library.db, p)) as response, open(dest, 'wb') as output:
                        while True:
                            if cancel.is_set():
                                raise Cancelled()
                            block = response.read(65536)
                            if not block:
                                break
                            got += len(block)
                            if got > meta['size']:
                                raise RuntimeError('Download larger than database size')
                            output.write(block)
                            progress('GET %d/%d %s' % (index + 1, len(paths), pathlib.PurePosixPath(p).name),
                                     (completed + got) / max(total, 1))
                        output.flush()
                        os.fsync(output.fileno())
                    if (dest.stat().st_size != meta['size'] if meta.get('rom') else not verified(dest, meta)):
                        raise RuntimeError('Download verification failed: ' + p)
                    if meta.get('rom'):
                        with zipfile.ZipFile(dest) as rom_zip:
                            if rom_zip.testzip() is not None:
                                raise RuntimeError('ROM ZIP integrity check failed: ' + p)
                    error = None
                    break
                except Cancelled:
                    raise
                except Exception as exc:
                    error = exc
                    if cancel.wait(0.4 * (attempt + 1)):
                        raise Cancelled()
            if error:
                raise error
            if meta.get('disk'):
                extract_disk(dest, meta, stage, cancel, progress)
            completed += meta['size']
        if cancel.is_set():
            raise Cancelled()
        # Check required MRA CRCs across staged ZIPs and existing parent/clone ZIPs.
        for i in library.selected:
            for names in library.games[i].get('rom_groups', []):
                required = getattr(names, 'crcs', set())
                if not required: continue
                found = set()
                for name in names:
                    relative = library.rom_folder+'/'+name
                    candidate = safe_path(stage, relative)
                    if not candidate.is_file(): candidate = safe_path(library.root, relative)
                    if candidate.is_file():
                        with zipfile.ZipFile(candidate) as archive:
                            found.update(entry.CRC for entry in archive.infolist())
                if not required.issubset(found):
                    raise RuntimeError('Required ROM CRCs missing: '+'|'.join(names))
        # Journal backups allow rollback on a filesystem error. Do not remove old RBFs.
        journal = []
        try:
            for index, p in enumerate(paths):
                dest = safe_path(library.root, p)
                meta = library.db['files'][p]
                if (dest.is_file() if (meta.get('rom') or meta.get('disk')) else verified(dest, meta)):
                    continue
                if dest.exists() and not meta.get('overwrite', True):
                    raise RuntimeError('Database protects existing file: ' + p)
                dest.parent.mkdir(parents=True, exist_ok=True)
                backup = stage / ('backup-%d' % index)
                existed = dest.exists()
                if existed:
                    shutil.copy2(dest, backup)
                journal.append((dest, backup if existed else None))
                os.replace(safe_path(stage, p), dest)
            os.sync()
        except Exception:
            try:
                for dest, backup in reversed(journal):
                    if backup is not None:
                        os.replace(backup, dest)
                    elif dest.exists():
                        dest.unlink()
            except Exception as rollback_error:
                preserve_stage = True
                raise RuntimeError('Rollback failed; recovery files retained in ' + str(stage)) from rollback_error
            os.sync()
            raise
        return len(paths)
    finally:
        if not preserve_stage:
            shutil.rmtree(stage)

# Compact 5x7 bitmap font. All drawing stays inside the 320x240 safe area.
FONT_ROWS = {
'A':'0E11111F111111','B':'1E11111E11111E','C':'0E11101010110E','D':'1E11111111111E',
'E':'1F10101E10101F','F':'1F10101E101010','G':'0E11101711110F','H':'1111111F111111',
'I':'0E04040404040E','J':'0702020212120C','K':'11121418141211','L':'1010101010101F',
'M':'111B1515111111','N':'11191513111111','O':'0E11111111110E','P':'1E11111E101010',
'Q':'0E11111115120D','R':'1E11111E141211','S':'0F10100E01011E','T':'1F040404040404',
'U':'1111111111110E','V':'11111111110A04','W':'11111115151B11','X':'11110A040A1111',
'Y':'11110A04040404','Z':'1F01020408101F','0':'0E11131519110E','1':'040C040404040E',
'2':'0E11010204081F','3':'1E01010601011E','4':'02060A121F0202','5':'1F10101E01011E',
'6':'0E10101E11110E','7':'1F010204080808','8':'0E11110E11110E','9':'0E11110F01010E',
' ':'00000000000000','.':'00000000000C0C',',':'00000000000408',':':'000C0C000C0C00',
'-':'0000001F000000','_':'0000000000001F','/':'01010204081010','\\':'10100804020101',
'!':'04040404040004','?':'0E110102040004',"'":'04040800000000','&':'0C12140C15120D',
'(':'02040808080402',')':'08040202020408','[':'0E08080808080E',']':'0E02020202020E',
'+':'0004041F040400','=':'00001F001F0000','>':'10080402040810','<':'01020408040201',
'*':'00150E1F0E1500','%':'19190204081313','|':'04040404040404','#':'0A0A1F0A1F0A0A','~':'00000916000000'}
FONT = {c: bytes.fromhex(rows) for c, rows in FONT_ROWS.items()}
BG, PANEL, CYAN, TEXT, MUTED, AMBER, INK = 0x101827, 0x1C2C43, 0x59DDCB, 0xECEDDC, 0x9BA9B9, 0xFFCA68, 0x101827

class Canvas:
    def __init__(self):
        self.data = bytearray(320 * 240 * 4)

    def box(self, x, y, w, h, color):
        x, y, w, h = int(x), int(y), int(w), int(h)
        x2, y2 = min(320, x + w), min(240, y + h)
        x, y = max(0, x), max(0, y)
        if x2 <= x or y2 <= y:
            return
        row = struct.pack('<I', color) * (x2 - x)
        if x == 0 and x2 == 320:
            self.data[y*1280:y2*1280] = row*(y2-y)
            return
        for yy in range(y, y2):
            start = (yy * 320 + x) * 4
            self.data[start:start + len(row)] = row

    _text_rows = {}

    def text(self, x, y, text, color=TEXT, width=296, scale=1, background=None):
        text = str(text).upper()[:max(0,width//(6*scale))]
        if not text: return
        pixels = len(text)*6*scale
        key = (text,color,scale,background)
        rows = self._text_rows.get(key)
        if rows is None:
            rows = []
            ink = int.from_bytes(struct.pack('<I',color)*pixels,'little')
            base = int.from_bytes(struct.pack('<I',background)*pixels,'little') if background is not None else 0
            for yy in range(7):
                mask = bytearray(pixels*4)
                for i,c in enumerate(text):
                    bits = FONT.get(c,FONT['?'])[yy]
                    for xx in range(5):
                        if bits & (16>>xx):
                            begin=(i*6+xx)*scale*4
                            mask[begin:begin+scale*4]=b'\xff'*(scale*4)
                value=int.from_bytes(mask,'little')
                row = ((base&~value)|(ink&value)).to_bytes(pixels*4,'little') if background is not None else (value,ink&value)
                rows.extend([row]*scale)
            if len(self._text_rows)>=1024: self._text_rows.clear()
            self._text_rows[key]=rows
        left,right=max(0,-x),min(pixels,320-x)
        if right<=left: return
        size=(right-left)*4
        limit=(1<<(size*8))-1
        shift=left*32
        for yy,row in enumerate(rows):
            if not 0<=y+yy<240: continue
            offset=((y+yy)*320+x+left)*4
            if isinstance(row,bytes):
                self.data[offset:offset+size]=row[left*4:right*4]
                continue
            mask,ink=row
            background=int.from_bytes(self.data[offset:offset+size],'little')
            result=(background&~((mask>>shift)&limit))|((ink>>shift)&limit)
            self.data[offset:offset+size]=result.to_bytes(size,'little')

    def label(self, x, y, text, color=TEXT, width=296, scale=1):
        background=struct.unpack_from('<I',self.data,(y*320+x)*4)[0]
        self.text(x,y,text,color,width,scale,background)

    def png(self, path):
        raw = bytearray()
        for y in range(240):
            raw.append(0)
            for x in range(320):
                i = (y * 320 + x) * 4
                raw.extend(self.data[i:i+3][::-1])
        def chunk(kind, data):
            return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xffffffff)
        pathlib.Path(path).write_bytes(b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB',320,240,8,2,0,0,0))
                                      + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b''))

class UI:
    def __init__(self):
        self.lib, self.online, self.busy = None, False, True
        self.message, self.fraction, self.focus = 'CHECKING INSTALLED FILES', 0, 0
        self.first, self.rows, self.error, self.tick = 0, [], '', 0

    def set_library(self, lib, online, message):
        self.lib, self.online, self.message, self.busy = lib, online, message, False
        self.rows = []
        for system, ids in lib.groups.items():
            if len(ids) > 1:
                self.rows.append(('group', system, ids))
            self.rows.extend(('game', lib.games[i]['name'], [i]) for i in ids)

    def progress(self, message, fraction=0):
        self.message, self.fraction = message, fraction

    def render(self):
        c = Canvas()
        c.box(0,0,320,240,BG)
        c.box(12,12,296,2,CYAN)
        c.label(12,21,'MEATCORES',TEXT,240,2)
        if self.busy:
            c.box(12,64,296,129,PANEL)
            c.label(22,77,'WORKING' + '.' * (self.tick % 4),CYAN)
            for row in range(5):
                c.label(22,96+row*11,self.message[row*45:(row+1)*45],TEXT,270)
            fraction = min(1.0, max(0.0, self.fraction))
            c.label(22,153,'['+'#'*int(fraction*28)+'-'*(28-int(fraction*28))+']',CYAN,230)
            c.label(268,153,'%3d%%' % int(fraction*100),TEXT,30)
            c.box(22,167,276,8,BG)
            for segment in range(int(fraction*46)):
                c.box(22+segment*6,167,5,8,CYAN)
            c.label(22,181,'B/ESC CANCEL AND EXIT',MUTED,276)
        elif self.lib is None:
            c.label(12,76,'ACTION FAILED',AMBER)
            for row in range(9):
                c.label(12,93+row*10,self.error[row*49:(row+1)*49],TEXT)
        else:
            buttons = [(12,92,'UPDATE ONLY'),(106,96,'SELECT ALL'),(204,104,'SELECT NONE')]
            for i,(x,w,label) in enumerate(buttons):
                c.box(x,56,w,15,CYAN if self.focus==i else PANEL)
                c.label(x+4,60,label,INK if self.focus==i else TEXT,w-6)
            list_focus = self.focus - 3
            if 0 <= list_focus < len(self.rows):
                if list_focus < self.first: self.first = list_focus
                if list_focus >= self.first+10: self.first = list_focus-9
            for row,item in enumerate(self.rows[self.first:self.first+10]):
                kind,name,ids = item
                eligible = {i for i in ids if self.lib.eligible(i)}
                chosen = self.lib.selected & eligible
                mark = '[X]' if eligible and chosen == eligible else ('[-]' if chosen else '[ ]')
                current = not eligible
                states = {self.lib.games[i]['state'] for i in ids}
                badge = '=' if states == {'CURRENT'} else ('!' if 'UPDATE' in states else ('~' if 'REPAIR' in states else '+'))
                if 'LOCAL NEWER' in states: badge = '>'
                if 'PROTECTED' in states: badge = '#'
                active = self.focus == 3 + self.first + row
                y = 76 + row*11
                if active or kind=='group': c.box(12,y-2,290,11,CYAN if active else PANEL)
                color = INK if active else (MUTED if current else (AMBER if kind=='group' else TEXT))
                prefix = '   ' if kind=='game' and len(self.lib.groups[self.lib.games[ids[0]]['system']])>1 else ''
                prefix = ' SYSTEM: ' if kind=='group' else prefix
                display = name
                room = 36-len(prefix)
                if len(display)>room:
                    offset = (self.tick//3) % (len(display)-room+10) if active else 0
                    offset = min(offset,max(0,len(display)-room))
                    display = display[offset:offset+room]
                c.label(14,y,mark+prefix+' '+display,color,270)
                c.label(289,y,badge,INK if active else (AMBER if badge in ('!','~') else MUTED),8)
            c.box(305,76,2,110,PANEL)
            c.box(305,76+int(99*self.first/max(1,len(self.rows)-10)),2,11,CYAN)
            count = len(self.lib.selected)
            c.label(12,195,'%02d SELECTED' % count,CYAN,110)
            updates = len({g['core'] for g in self.lib.games
                           if self.lib.states.get(g['core']) in ('NEW','UPDATE')})
            state = 'NEW UPDATES %d' % updates if self.online else 'OFFLINE / READ ONLY'
            c.label(150,195,state,AMBER,155)
        c.box(12,212,296,1,PANEL)
        c.label(12,217,'A/ENTER SELECT   B/ESC BACK',TEXT)
        c.label(12,227,'X/SHIFT DOWNLOAD   UP/DOWN MOVE',CYAN)
        return c

    def action(self, action):
        if action == 'back': return 'exit'
        if self.busy or self.lib is None: return None
        n = len(self.rows)+3
        if action in ('up','down','left','right'):
            self.focus = (self.focus + (-1 if action in ('up','left') else 1)) % n
            self.tick = 0
        elif action in ('pageup','pagedown'):
            self.focus = max(0,min(n-1,self.focus+(-9 if action=='pageup' else 9)))
            self.tick = 0
        elif action == 'download':
            if self.online and self.lib.selected: return 'download'
        elif action == 'select':
            if not self.online: return None
            if self.focus==0: self.lib.updates()
            elif self.focus==1: self.lib.selected = {i for i in range(len(self.lib.games)) if self.lib.eligible(i)}
            elif self.focus==2: self.lib.selected.clear()
            else: self.lib.choose(self.rows[self.focus-3][2])
        return None

def mister_command(command):
    fd = os.open('/dev/MiSTer_cmd', os.O_WRONLY | os.O_NONBLOCK)
    try: os.write(fd,(command+'\n').encode())
    finally: os.close(fd)

DISPLAY_SHA256 = '7cc39da672ab15b2e548809a405634924dd46bab91a56c1a29ce770ce94a166a'

def unpack_display(cache):
    target = cache / ('display-' + DISPLAY_SHA256[:12] + '.rbf')
    if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == DISPLAY_SHA256:
        return target
    source = pathlib.Path(os.environ['MEATCORES_SELF']).read_bytes()
    encoded = source.rsplit(b'\n# MEATCORES_DISPLAY_PAYLOAD\n',1)[1].split(b'\n# MEATCORES_SOURCE_PAYLOAD\n',1)[0]
    core = zlib.decompress(base64.b64decode(encoded))
    if hashlib.sha256(core).hexdigest() != DISPLAY_SHA256:
        raise RuntimeError('Embedded display core is damaged; recopy MEATCORES.sh')
    tmp = target.with_suffix('.tmp')
    tmp.write_bytes(core)
    os.replace(tmp,target)
    return target

class Display:
    """Boomer's native 240p transport, controlled by stock MiSTer Main.

    The display bitstream is embedded below the Python payload. It is not a game
    download, does not require a custom MiSTer binary, and leaves MiSTer.ini alone.
    """
    def __init__(self, cache):
        self.fd, self.mem, self.loaded, self.pending = None, None, False, None
        if os.uname().machine != 'armv7l':
            raise RuntimeError('Native display requires MiSTer ARM Linux; use --preview on a PC')
        if not pathlib.Path('/media/fat/menu.rbf').is_file():
            raise RuntimeError('Missing menu.rbf; cannot guarantee return to MiSTer')
        core = unpack_display(cache)
        # Linux ARM kuser ABI: full DMB before publishing the aligned DDR control word.
        self.barrier = ctypes.CFUNCTYPE(None)(0xffff0fa0)
        self.barrier()
        self.colors = [BG,PANEL,CYAN,TEXT,MUTED,AMBER]
        table = bytearray(256)
        for i,color in enumerate(self.colors): table[color & 255] = i
        self.lookup = bytes(table)
        try:
            mister_command('load_core ' + str(core))
            self.loaded = True
            deadline = time.monotonic()+8
            while time.monotonic()<deadline:
                time.sleep(.005)
                if pathlib.Path('/tmp/CORENAME').read_text().strip() == 'MEATCORES': break
            else: raise RuntimeError('Display core did not start')
            self.fd = os.open('/dev/mem',os.O_RDWR|os.O_SYNC)
            self.mem = mmap.mmap(self.fd,0x400000,mmap.MAP_SHARED,mmap.PROT_READ|mmap.PROT_WRITE,offset=0x3a000000)
            self.write(0,0)
            self.write(0x134008,3)  # Indexed8 + native 320x240; no 200-line crop.
            self.write(0x30,self.read(0x38))  # Empty audio ring; launcher is silent.
            self.write(0x134000,0x4e424c44)
            for i,rgb in enumerate(self.colors):
                struct.pack_into('<H',self.mem,0x25840+i*2,((rgb>>8)&0xf800)|((rgb>>5)&0x7e0)|((rgb>>3)&31))
            self.counter = self.read(0x10)>>2
            self.startup_deadline = time.monotonic()+4
        except Exception:
            self.close()
            raise

    def read(self, offset):
        return ctypes.c_uint32.from_buffer(self.mem,offset).value

    def write(self, offset, value):
        self.barrier()
        ctypes.c_uint32.from_buffer(self.mem,offset).value = value
        self.barrier()

    def present(self, canvas):
        deadline = max(self.startup_deadline,time.monotonic()+.25)
        while self.pending is not None and self.read(0x10)!=self.pending:
            if time.monotonic()>deadline:
                raise RuntimeError('Display acknowledgement timeout (wanted %08x / feedback %08x / control %08x)' % (self.pending,self.read(0x10),self.read(0)))
            time.sleep(.001)
        page = 1-(self.read(0x10)&1)
        offset = (0x25a40,0x70a40)[page]
        indexed = bytes(canvas.data[::4]).translate(self.lookup)
        self.mem[offset:offset+len(indexed)] = indexed
        self.counter = (self.counter+1)&0x3fffffff
        self.pending = (self.counter<<2)|2|page
        self.write(0,self.pending)

    def close(self):
        if self.mem is not None:
            self.write(0,0)
            self.mem.close(); self.mem = None
        if self.fd is not None: os.close(self.fd); self.fd = None
        if self.loaded:
            try: mister_command('load_core /media/fat/menu.rbf')
            except OSError: pass
            self.loaded = False

class Inputs:
    # MiSTer Main owns evdev and forwards its mapped inputs through hps_io.
    # This preserves its global mapping, unique-device mapping and device quirks.
    EVENT = struct.Struct('@llHHi')  # Also used by the hardware uinput test.
    KEYS = {0x75:'up',0x72:'down',0x6b:'left',0x74:'right',
            0x275:'up',0x272:'down',0x26b:'left',0x274:'right',
            0x5a:'select',0x25a:'select',0x29:'select',0x76:'back',
            0x12:'download',0x59:'download',0x27d:'pageup',0x27a:'pagedown'}
    BUTTONS = ('right','left','down','up','select','back','download')
    def __init__(self, display):
        self.display, self.held = display, {}
        self.previous = self.joy()
        display.write(0x122030,display.read(0x122028)%256)

    def joy(self):
        bits = 0
        for address in (0x08,0x18,0x20,0x28): bits |= self.display.read(address)
        axis = self.display.read(0x122038)
        x,y = struct.unpack('bb',struct.pack('<H',axis&0xffff))
        if x < -48: bits |= 2
        if x > 48: bits |= 1
        if y < -48: bits |= 8
        if y > 48: bits |= 4
        return bits & 127

    def poll(self, timeout=0.004):
        time.sleep(timeout)
        now, events = time.monotonic(), []
        r = self.display.read(0x122030)%256
        w = self.display.read(0x122028)%256
        while r != w:
            raw = self.display.read(0x123000+r*4)
            r = (r+1)%256
            key = ('key',raw&0x2ff)
            action = self.KEYS.get(key[1])
            if not raw&0x100:
                self.held.pop(key,None)
            elif action and key not in self.held:
                events.append(action)
                self.held[key] = (action,now+.24)
        self.display.write(0x122030,r)
        bits = self.joy()
        for bit,action in enumerate(self.BUTTONS):
            mask,key = 1<<bit,('joy',bit)
            if not bits&mask:
                self.held.pop(key,None)
            elif not self.previous&mask:
                events.append(action)
                self.held[key]=(action,now+.24)
        self.previous=bits
        for key,(action,next_at) in list(self.held.items()):
            if action in ('up','down','left','right') and now>=next_at:
                events.append(action)
                self.held[key]=(action,now+.06)
        return events

    def close(self):
        self.held.clear()


class InputPump:
    # Keep sampling while a frame is drawn so quick press/release edges survive.
    def __init__(self, adapter):
        self.adapter, self.events = adapter, queue.Queue()
        self.stop, self.error = threading.Event(), None
        self.thread = threading.Thread(target=self.sample, daemon=True)
        self.thread.start()

    def sample(self):
        try:
            while not self.stop.is_set():
                for event in self.adapter.poll(.004): self.events.put(event)
        except Exception as error:
            self.error = error

    def poll(self):
        if self.error is not None: raise self.error
        events = []
        try:
            events.append(self.events.get(timeout=.004))
            while True: events.append(self.events.get_nowait())
        except queue.Empty: return events

    def close(self):
        self.stop.set(); self.thread.join()
        self.adapter.close()

def sync_menu_maps(root):
    # MiSTer stores its virtual SNES layout in 32 little-endian words. Translate
    # menu confirm/cancel plus the left face button into our three action slots.
    # Only MEATCORES-specific maps are generated; global maps are never edited.
    folder = root/'config/inputs'
    for source in folder.glob('input_*_v3.map'):
        data = source.read_bytes()
        if len(data) != 128: continue
        menu = struct.unpack('<32I', data)
        core = list(menu)
        core[4] = (menu[23] & 0xffff) or menu[5]
        core[5] = (menu[23] >> 16) or menu[4]
        core[6] = menu[7]  # Left face: virtual SNES Y / Xbox X.
        for i in range(7,20): core[i] = 0
        # Main synthesizes stick direction keys at KEY_EMU (768) + axis*2.
        for axis, negative, positive in ((28,1,0),(29,3,2)):
            if menu[axis]:
                key = 768+((menu[axis]&0xffff)*2)
                core[negative] = (core[negative]&0xffff)|(key<<16)
                core[positive] = (core[positive]&0xffff)|((key+1)<<16)
        payload = struct.pack('<32I', *core)
        target = folder/('MEATCORES_'+source.name)
        if target.is_file() and target.read_bytes() == payload: continue
        temporary = None
        try:
            fd, name = tempfile.mkstemp(prefix='.meatcores-map-',dir=folder)
            temporary = pathlib.Path(name)
            with os.fdopen(fd,'wb') as out:
                out.write(payload); out.flush(); os.fsync(out.fileno())
            os.replace(temporary,target)
        finally:
            if temporary is not None and temporary.exists(): temporary.unlink()

def run_ui(root):
    ui, cancel = UI(), threading.Event()
    cache = root/'Scripts/.config/meatcores'
    cache.mkdir(parents=True,exist_ok=True)
    lock = open(cache/'lock','w')
    try: fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
    except BlockingIOError: raise RuntimeError('MEATCORES is already running')
    display, inputs, worker, music = None, None, None, None
    pool = concurrent.futures.ThreadPoolExecutor(max_workers=1)
    def startup():
        db,online,message=load_db(cache)
        lib=Library(db,root)
        if online: prepare_roms(lib,cache/'mras',ui.progress,cancel)
        lib.scan(ui.progress,cancel)
        return lib,online,message
    try:
        # Start the tiny music fetch while the catalogue and 240p core load.
        # It never shares the renderer or catalogue worker, so input/frame timing
        # stays unchanged even on a first run with an empty cache.
        music = MenuMusic(cache)
        worker=pool.submit(startup)
        sync_menu_maps(root)
        display=Display(cache)
        display.present(ui.render())
        inputs=InputPump(Inputs(display))
        music.begin()
        operation='startup'; last=None; last_signature=None; next_tick=0
        while True:
            if worker is not None and worker.done():
                try:
                    result=worker.result()
                    if operation=='startup': ui.set_library(*result)
                    else:
                        break  # Verified installation finished; return to MiSTer immediately.
                except Cancelled:
                    ui.busy=False
                except Exception as exc:
                    ui.busy=False; ui.error=str(exc)
                    (cache/'last-error.log').write_text(str(exc)+'\n')
                    # Keep failures visibly readable; do not claim a successful install.
                    ui.lib=None
                worker=None
            for action in inputs.poll():
                command=ui.action(action)
                if command=='exit':
                    cancel.set()
                    return
                elif command=='download' and worker is None:
                    ui.busy=True; ui.fraction=0
                    def download():
                        count=install(ui.lib,cancel,ui.progress)
                        return count
                    operation='download'; worker=pool.submit(download)
            if time.monotonic()>=next_tick:
                ui.tick+=1; next_tick=time.monotonic()+0.25
            signature=(ui.message,ui.fraction,ui.tick,ui.focus,ui.busy,ui.error,
                       id(ui.lib),tuple(sorted(ui.lib.selected)) if ui.lib else ())
            if signature != last_signature:
                canvas=ui.render()
                if canvas.data != last:
                    display.present(canvas); last=canvas.data
                last_signature=signature
    finally:
        cancel.set()
        if inputs: inputs.close()
        if music: music.close()
        if display: display.close()
        # Restore the user's video/input immediately even if a socket is timing out.
        pool.shutdown(wait=True)
        lock.close()

def main():
    signal.signal(signal.SIGTERM,lambda *_: (_ for _ in ()).throw(KeyboardInterrupt()))
    parser=argparse.ArgumentParser(description='MEATCORES standalone MiSTer core downloader')
    parser.add_argument('--root',type=pathlib.Path,default=ROOT)
    parser.add_argument('--catalog',type=pathlib.Path,help='Read-only catalogue/status JSON output')
    parser.add_argument('--preview',type=pathlib.Path,help='Write a 320x240 PNG without touching display/input')
    parser.add_argument('--db',type=pathlib.Path,help='Use a local DB ZIP for read-only catalogue/preview checks')
    parser.add_argument('--extract-display-source',type=pathlib.Path,help='Extract embedded FPGA source and license notices')
    args=parser.parse_args()
    args.root=args.root.resolve()
    if not (args.catalog or args.preview or args.db or args.extract_display_source):
        self_update()
    if args.extract_display_source:
        target=args.extract_display_source.resolve()
        source=pathlib.Path(os.environ['MEATCORES_SELF']).read_bytes()
        packed=base64.b64decode(source.rsplit(b'\n# MEATCORES_SOURCE_PAYLOAD\n',1)[1])
        with tarfile.open(fileobj=io.BytesIO(packed),mode='r:gz') as archive:
            for member in archive.getmembers():
                name=member.name.rstrip('/')
                dest=safe_path(target,name)
                if member.isdir(): dest.mkdir(parents=True,exist_ok=True)
                elif member.isfile():
                    dest.parent.mkdir(parents=True,exist_ok=True)
                    with archive.extractfile(member) as src, open(dest,'wb') as out: shutil.copyfileobj(src,out)
                else: raise ValueError('Unexpected source archive member')
        print('Display source and license notices extracted to '+str(target))
        return
    if args.db and not (args.catalog or args.preview): parser.error('--db is read-only; use --catalog or --preview')
    if args.catalog or args.preview:
        db=parse_db(args.db.read_bytes()) if args.db else load_db(args.root/'Scripts/.config/meatcores')[0]
        lib=Library(db,args.root); lib.scan()
        if args.catalog:
            args.catalog.write_text(json.dumps(lib.games,indent=2)+'\n')
        if args.preview:
            ui=UI(); ui.set_library(lib,True,''); ui.focus=3; ui.render().png(args.preview)
        return
    run_ui(args.root)

if __name__=='__main__':
    try: main()
    except KeyboardInterrupt: sys.exit(130)
    except SystemExit: raise
    except Exception as error:
        print('MEATCORES: '+str(error),file=sys.stderr)
        sys.exit(1)
